SetQuitOnError(true);SetColumns(0);tt:=Cputime();S:=CuspidalSubspace(ModularSymbolsH(61,[1],2,1));e:=WindingElementProjection(S);T2:=Transpose(DualHeckeOperator(S,2));T3:=Transpose(DualHeckeOperator(S,3));rows:=[];v:=e;for k in [0..125]do Append(~rows,Eltseq(v));v:=v*T2;end for;W:=Matrix(Rationals(),rows);print "CORRECT_WINDING_RANK",Rank(W),Cputime(tt);
K:=BasisMatrix(Kernel(Transpose(W)));TB:=Solution(K,K*Transpose(T3));bad:=CharacteristicPolynomial(TB);print "BAD_T3_POLYNOMIAL",bad;assert Rank(VerticalJoin(W,Evaluate(bad,T3))) eq Rank(W);
pol:=CharacteristicPolynomial(T3);fac:=Factorization(pol);kill:=&*[Parent(pol)|f[1]^f[2]:f in fac|f[2] ge 2 or IsZero(e*Evaluate(ExactQuotient(pol,f[1]^f[2]),T3))];print "T3_KILL",kill,Rank(Evaluate(kill,T3)),Rank(VerticalJoin(W,Evaluate(kill,T3)));
T5:=Transpose(DualHeckeOperator(S,5));TB5:=Solution(K,K*Transpose(T5));bad5:=CharacteristicPolynomial(TB5);print "BAD_T5_POLYNOMIAL",bad5;assert Rank(VerticalJoin(W,Evaluate(bad5,T5))) eq Rank(W);print "CORRECT_WINDING_COMPLETE";quit;
